        public ImageItemsCollection(string folderPath, MovieImage parent)
        {
            Parent = parent;
            //Speed = Parent.Speed;
            folderPath = Support.Support.FixImagePath(folderPath);
            if (!string.IsNullOrEmpty(folderPath))
            {
                if (Parent.FolderType == cstImageList || Parent.FolderType == null)
                {
                    ReloadImageItems(folderPath);
                }
                else
                {
                    List<MovieImage> tempList = new List<MovieImage>();
                    // is a list of folder
                    folderPath = Support.Support.FixImagePath(folderPath).Trim();

                    if (folderPath.Contains(".."))
                    {
                        folderPath = folderPath.Substring(0, folderPath.Length - 2);
                    }

                    this.BuildSubDirectoryList(folderPath);
                }
            }
        }

        private void BuildSubDirectoryList(string folderPath)
        {
            List<string> dir = Directory.EnumerateDirectories(folderPath).ToList();
            if (Parent != null)
            {
                if (Parent.SubDirectoryList == null) Parent.SubDirectoryList = new ObservableCollection<MovieImage>();
                foreach (var item in dir)
                {
                    if (item != folderPath)
                    {
                        // see if already found
                        MovieImage? images = Parent.SubDirectoryList.Where(i => i.Path.ToLower() == item.ToLower()).FirstOrDefault();

                        if (images == null)
                        {
                            images = new MovieImage()
                            {
                                Path = item,
                                Name = Path.GetFileNameWithoutExtension(item),
                                Id = 0,
                                Speed = 5,
                                FolderType = cstImageList,
                                ParentId = Parent.Id
                            };

                            Parent.SubDirectoryList.Add(images);
                            images.Insert();
                        }
                    }
                }

                //if (tempList.Count > 0)   Parent.SubDirectoryList = new ObservableCollection<Images>(tempList);
            }
        }

        internal List<ImageItem> SortList()
        {
            List<ImageItem> tempList = this.OrderBy(i => i.ImageName).ToList();

            return tempList;
        }

        internal void ReloadImageItems(string folderPath)
        {
            folderPath = Support.Support.FixImagePath(folderPath);
            if (Directory.Exists(folderPath))
            {
                this.Clear();
                List<string> files = Directory
                            .EnumerateFiles(folderPath, "*.*", SearchOption.AllDirectories)
                            .Where(
                                s =>
                                    s.EndsWith(".JPG", StringComparison.OrdinalIgnoreCase)
                                    || s.EndsWith(".BMP", StringComparison.OrdinalIgnoreCase)
                                    || s.EndsWith(".PNG", StringComparison.OrdinalIgnoreCase)
                            ).ToList();
                int index = this.Count + 1;
                foreach (string file in files)
                {
                    // see if we have the item already
                    ImageItem? item = this.Find(i => i.ImagePath == file);
                    if (item == null)
                    {
                        item = new ImageItem() { ImagePath = file, Id = index };
                        this.Add(item);
                        index += 1;
                    }
                }

                // sort the list by image name
                List<ImageItem> tempList = this.OrderBy(i => i.ImageName).ToList();
                this.Clear();
                foreach (var item in tempList)
                {
                    this.Add(item);
                }
            }
        }

