        //private SolidColorBrush backgroundColor;
        public async void Play()
        {
            IsPlaying = !IsPlaying;
            if (Index >= 0 && Index < this.Count)
            {
                args.ImageItem = this[Index];
                if (IsPlaying)
                {
                    args.Action = "Pause";
                    ISVM.CurrentIcon = ISVM.PauseIcon;
                    ISVM.PlayPauseLabel = "Pause";
                    ISVM.backgroundColor = Avalonia.Media.Brushes.LightGreen;
                }
                else
                {
                    args.Action = "Play";
                    ISVM.CurrentIcon = ISVM.PlayIcon;
                    ISVM.PlayPauseLabel = "Play";
                    ISVM.backgroundColor = Avalonia.Media.Brushes.PaleGoldenrod;
                }
                args.ImagePosition = Index;

                this.PostButtonChanges();
            }
            OnImageChanged(args);
            if (IsPlaying)
            {
                while (Index < this.Count && IsPlaying)
                {
                    if (this.Speed == null) this.Speed = 5;
                    System.Threading.Thread.Sleep((int)(this.Speed.Value * 1000));
                    MoveNext();
                }
                if (index >= this.Count)
                {
                    args.Action = "Stopped";
                    Index = 0;
                    OnImageChanged(args);
                    ISVM.backgroundColor = Avalonia.Media.Brushes.LightGray;
                }
            }
        }

        private void PostButtonChanges()
        {
            Dispatcher.UIThread.Post(() =>
            {
                ISVM.PlayButton.ImageSource = ISVM.CurrentIcon;
                ISVM.PlayButton.LabelText = ISVM.PlayPauseLabel;
                ISVM.PlayButton.Background = ISVM.backgroundColor;
            });
        }

        internal void MoveNext()
        {
            string action = "Play";
            if (IsPlaying)
            {
                action = "Play";
            }
            else if (args.Action == "Stopped") action = "Step";
            Index += 1;
            if (Index < this.Count)
            {
                args.ImagePosition = Index;
                args.ImageItem = this[Index];
                args.Action = action;
                //MVVM.RootFolder.CurrentImageItem = this[Index];
                OnImageChanged(args);
            }

        }
        internal void MovePrev()
        {
            string action = "Play";

            if (IsPlaying)
            {
            }
            else if (args.Action == "Stopped") action = "Step";
            Index -= 1;
            if (Index > 0)
            {
                args.ImagePosition = Index;
                args.ImageItem = this[Index];
                args.Action = action;
                //MVVM.RootFolder.CurrentImageItem = this[Index];
                OnImageChanged(args);
            }
        }

        internal void StopPlaying()
        {
            if (IsPlaying)
            {
                Index = this.Count;
                IsPlaying = false;
                // chang Current icon to play and change playtext to play
                ISVM.CurrentIcon = ISVM.PlayIcon;
                ISVM.PlayPauseLabel = "Play";

                ISVM.PlayButton.ImageSource = ISVM.PlayIcon;
                ISVM.PlayButton.LabelText = "Play";
                ISVM.backgroundColor = new SolidColorBrush(Avalonia.Media.Colors.LightGray);

                System.Threading.Thread.Sleep(100);

                this.PostButtonChanges();
            }
        }

